import json
import re
d = json.load(open('/app/resources/treasury_bulletin_1982_03.json'))
# Find the element with the PDO-1 table
for i, el in enumerate(d['document']['elements']):
    content = str(el.get('content', ''))
    if 'Mar. 31' in content and '1982' in content and '7-7/8Z-G Note' in content:
        # Print lines between 1982 and 1983
        lines = content.split('<tr>')
        for j, line in enumerate(lines):
            if '<td>1982</td>' in line:
                # Print the next several lines until we see 1983
                for k in range(j+1, min(j+30, len(lines))):
                    print(lines[k][:300])
                    if '<td>1983</td>' in lines[k]:
                        break
                break
        break"
